#include "model/arch_qwen.hpp"
#include <array>
#include <chrono>
#include <iomanip>
#include <iostream>
using Clock = std::chrono::steady_clock;
struct Stat { size_t calls = 0; double ms = 0; };
class ProfileBackend : public backend::CpuBackend {
public:
    bool enabled = false, nested = false;
    int ff = 0;
    std::array<Stat, 7> stats{};
    void add(size_t kind, Clock::time_point start) {
        ++stats[kind].calls;
        stats[kind].ms += std::chrono::duration<double, std::milli>(Clock::now() - start).count();
    }
    void matmul(uint32_t type, const uint8_t* data, const float* x, float* y,
                size_t nin, size_t nout, size_t batch) override {
        if (!enabled || nested) { CpuBackend::matmul(type, data, x, y, nin, nout, batch); return; }
        const size_t kind = nout > 30000 ? 4 : nin == size_t(ff) ? 3 : 2;
        auto start = Clock::now();
        CpuBackend::matmul(type, data, x, y, nin, nout, batch);
        add(kind, start);
    }
    void matmul_group(std::initializer_list<backend::Projection> p, const float* x,
                      size_t nin, size_t batch) override {
        if (!enabled) { CpuBackend::matmul_group(p, x, nin, batch); return; }
        if (p.size() != 2 && p.size() != 3) throw std::runtime_error("unexpected group");
        nested = true;
        auto start = Clock::now();
        CpuBackend::matmul_group(p, x, nin, batch);
        add(p.size() == 3 ? 0 : 1, start);
        nested = false;
    }
    void attention(const float* q, const float* k, const float* v, float* out,
                   int nh, int nk, int hd, int past, int batch, size_t stride) override {
        if (!enabled) { CpuBackend::attention(q, k, v, out, nh, nk, hd, past, batch, stride); return; }
        nested = true;
        auto start = Clock::now();
        CpuBackend::attention(q, k, v, out, nh, nk, hd, past, batch, stride);
        add(5, start);
        nested = false;
    }
    void parallel_for(int n, const std::function<void(int)>& fn) override {
        if (!enabled || nested) { CpuBackend::parallel_for(n, fn); return; }
        auto start = Clock::now();
        CpuBackend::parallel_for(n, fn);
        add(6, start);
    }
    void dump(const char* phase, double total) {
        const char* names[] = {"qkv", "gate_up", "attn_output", "ffn_down", "output", "attention", "parallel_for"};
        std::cout << "\"" << phase << "\":{\"total_ms\":" << total << ",\"ops\":[";
        for (size_t i = 0; i < stats.size(); ++i) {
            if (i) std::cout << ',';
            std::cout << "{\"name\":\"" << names[i] << "\",\"calls\":" << stats[i].calls << ",\"ms\":" << stats[i].ms << '}';
        }
        std::cout << "]}";
    }
};
int main(int argc, char** argv) {
    if (argc != 4) return 2;
    auto weights = gguf::read_gguf(argv[1]);
    auto backend = std::make_shared<ProfileBackend>();
    const auto cfg = infer::load_config(weights);
    if (cfg.n_embd != 1024 || cfg.n_ff != 3072 || cfg.n_layer != 28) return 3;
    backend->ff = cfg.n_ff;
    infer::Model model(weights, backend);
    const int threads = std::stoi(argv[3]);
    model.set_threads(threads); model.set_ubatch(128);
    std::ifstream input(argv[2]); std::vector<uint32_t> ids; uint32_t id;
    while (input >> id) ids.push_back(id);
    if (ids.size() != 247) return 4;
    std::vector<uint32_t> prompt(ids.begin(), ids.begin() + 215);
    uint64_t control_hash = 0;
    for (int run = 0; run < 3; ++run) {
        model.reset(); backend->enabled = run > 0; backend->stats = {};
        auto start = Clock::now(); auto logits = model.prefill(prompt);
        const double pp = std::chrono::duration<double, std::milli>(Clock::now() - start).count();
        if (run) {
            std::cout << std::setprecision(12) << "{\"run\":" << run << ",\"threads\":" << threads << ',';
            backend->dump("pp", pp);
        }
        backend->stats = {}; start = Clock::now();
        for (size_t i = 215; i < ids.size(); ++i) logits = model.step(ids[i]);
        const double tg = std::chrono::duration<double, std::milli>(Clock::now() - start).count();
        backend->enabled = false;
        uint64_t hash = 14695981039346656037ull;
        for (float value : logits) {
            if (!std::isfinite(value)) return 5;
            uint32_t bits; std::memcpy(&bits, &value, 4);
            for (int shift = 0; shift < 32; shift += 8) { hash ^= (bits >> shift) & 255; hash *= 1099511628211ull; }
        }
        if (!run) control_hash = hash;
        else {
            if (hash != control_hash) return 6;
            std::cout << ','; backend->dump("tg", tg);
            std::cout << ",\"final_vector_fnv64\":\"" << std::hex << hash << std::dec << "\"}\n" << std::flush;
        }
    }
}

