from pathlib import Path
import subprocess,json,os,statistics,hashlib
r=Path(os.environ['TEMP'])/'llmx-worker-profile'
models={'q8':Path.home()/'.cache/huggingface/hub/models--Qwen--Qwen3-0.6B-GGUF/snapshots/23749fefcc72300e3a2ad315e1317431b06b590a/Qwen3-0.6B-Q8_0.gguf','f32':r.parent/'Qwen3-0.6B-F32.gguf'}
ids=r.parent/'llmx-external-perf/eight-pairs/tokens.txt'
rows=[];hashes={}
for pair in range(3):
 for model in (['q8','f32'] if pair%2==0 else ['f32','q8']):
  for threads in ([1,6] if pair%2==0 else [6,1]):
   for arm in (['control','current'] if pair%2==0 else ['current','control']):
    active=subprocess.check_output(['powershell','-NoProfile','-Command',"Get-CimInstance Win32_Process -Filter \"Name='llmx.exe'\" | Select-Object -ExpandProperty ProcessId"],text=True).strip()
    if active:raise RuntimeError('User llmx process still present; do not start profiling: '+active)
    cmd=[str(r/(arm+'.exe')),str(models[model]),str(ids),str(threads)]
    p=subprocess.run(cmd,capture_output=True,timeout=180)
    name=f'{model}-t{threads}-pair{pair}-{arm}'
    (r/(name+'.stdout')).write_bytes(p.stdout);(r/(name+'.stderr')).write_bytes(p.stderr)
    active=subprocess.check_output(['powershell','-NoProfile','-Command',"Get-CimInstance Win32_Process -Filter \"Name='llmx.exe'\" | Select-Object -ExpandProperty ProcessId"],text=True).strip()
    if active:
     (r/(name+'.contended')).write_text(active)
     raise RuntimeError('User chat started during profile; retained raw sample without admitting it: '+active)
    p.check_returncode();records=[json.loads(x) for x in p.stdout.splitlines()];assert len(records)==2
    for record in records:
     assert record['threads']==threads
     for phase in ['pp','tg']:
      assert 0<sum(x['ms'] for x in record[phase]['ops'])<=record[phase]['total_ms']
      qkv=next(x for x in record[phase]['ops'] if x['name']=='qkv');assert qkv['calls']==(56 if phase=='pp' else 896),qkv
     h=record['final_vector_fnv64']
     if model in hashes:assert hashes[model]==h
     else:hashes[model]=h
    rows.append(dict(model=model,threads=threads,pair=pair,arm=arm,command=cmd,records=records))
    (r/'results.json').write_text(json.dumps(rows,indent=2));print(name,'pass',flush=True)
summary=[]
for model in models:
 for threads in [1,6]:
  for phase in ['pp','tg']:
   item=dict(model=model,threads=threads,phase=phase)
   for arm in ['control','current']:
    runs=[y for x in rows if x['model']==model and x['threads']==threads and x['arm']==arm for y in x['records']]
    item[arm]={'total_mean_ms':statistics.mean(x[phase]['total_ms'] for x in runs),'total_median_ms':statistics.median(x[phase]['total_ms'] for x in runs),'ops':{op:statistics.mean(next(o['ms'] for o in x[phase]['ops'] if o['name']==op) for x in runs) for op in ['qkv','gate_up','attn_output','ffn_down','output','attention','parallel_for']}}
   summary.append(item)
(r/'summary.json').write_text(json.dumps(summary,indent=2));print(json.dumps(summary,indent=2))

